-- 0034 약관·개인정보처리방침 1.1(시행 2026-10-17, 시행 7일 전 공지 — 이용약관 제12조).
-- 이용약관: 제8조에 크레딧(이 플랫폼 이용권, 양도·현금 환급 불가)·포인트(무상 적립, 양도·현금 환급 불가) 조항(LEGAL-010).
-- 개인정보처리방침: 국외 이전 표에 이전 시점·방법과 보유 기간(LEGAL-002).
-- 1.0 은 화면 코드(apps/web/app/lib/docs-content.ts) 원문 그대로 둔다 — 회원이 이미 동의한 판이라 고치지 않는다.
-- 시행일이 지나면 Consents::version() 이 t1.1|p1.1 로 바뀌어 다음 로그인 때 다시 동의 받는다(LEGAL-012).
-- 같은 문서 1.1 이 이미 있으면(관리자가 먼저 만든 경우) 넣지 않는다.
INSERT INTO core_policy_versions (public_id, doc, version, effective_on, summary, spec, published)
SELECT 'pol11terms0034aa', 'terms', '1.1', '2026-10-17', '제8조 크레딧·포인트 조항 추가(이용권, 양도·현금 환급 불가)', '{"title":"이용약관","lead":"powerPlus 를 이용하시기 전에 아래 약관을 읽어 주세요. 가입하거나 서비스를 이용하면 이 약관에 동의한 것으로 봅니다.","draft":"이 문서는 법무 검토 전 초안입니다. 정식 공개 전에 내용이 바뀔 수 있습니다.","blocks":[{"id":"purpose","title":"제1조 목적","paras":["이 약관은 ㈜솔리데오(이하 \\"회사\\")가 제공하는 powerPlus 와 그 안의 모듈, powerMCP·REST API(이하 \\"서비스\\")의 이용 조건을 정합니다."]},{"id":"definitions","title":"제2조 용어","items":["회원: 이메일 인증 또는 소셜 로그인으로 가입한 사람입니다.","모듈: powerAssets·powerDeck·powerMock·powerGuide 와 커뮤니티입니다.","업로드 파일: 회원이 장표 변환 등을 위해 올린 파일입니다.","결과물: 서비스가 회원의 요청으로 만든 장표·시안·코드입니다.","API 키: powerMCP 와 REST API 를 부를 때 쓰는 인증 키입니다."]},{"id":"join","title":"제3조 가입과 나이","paras":["만 14세 이상만 가입할 수 있습니다.","회사 이메일로 인증한 임직원은 임직원 계정으로 분류됩니다."]},{"id":"service","title":"제4조 서비스 내용","items":["powerAssets: 아이콘·사진·일러스트·장표 에셋 검색과 PowerPoint 애드인 삽입","powerDeck: 초안 장표와 자료를 정리된 장표로 변환","powerMock: 홈페이지 기획·목업·시안 판정과 컴포넌트 코드","powerGuide: 디자인 토큰·부품·KRDS 대응표·접근성 안내(무료)","powerMCP·REST API: AI 도구와 코드에서 위 기능 호출"]},{"id":"upload","title":"제5조 업로드 파일","paras":["회원은 올린 파일에 대한 권리를 가지고 있거나 이용 허락을 받았음을 보증합니다.","회사는 업로드 파일을 요청한 작업에만 씁니다. 작업이 끝나고 7일이 지나면 원본과 중간 자료를 지웁니다.","개인정보나 대외비가 담긴 문서는 올리지 않는 것을 권합니다."]},{"id":"ai","title":"제6조 AI 생성물","paras":["결과물과 일부 에셋은 생성형 AI 로 만듭니다. 화면과 내려받은 파일에 AI 생성임을 표시합니다.","결과물의 권리는 요청한 회원에게 있습니다. 다만 결과물에 들어간 powerPlus 에셋은 사용 허락만 드립니다.","AI 결과물과 판정 점수는 참고용이며 정확성을 보증하지 않습니다."]},{"id":"account","title":"제7조 계정과 탈퇴","paras":["회원은 계정과 API 키를 안전하게 관리해야 합니다. 키가 새면 마이페이지에서 바로 폐기해 주세요.","마이페이지에서 언제든 탈퇴할 수 있습니다. 탈퇴하면 개인정보를 지우고, 올린 글은 작성자를 익명으로 바꿉니다."]},{"id":"payment","title":"제8조 유료 서비스·크레딧·포인트","paras":["유료 요금제의 결제·해지·환불 조건은 요금제를 공개할 때 이 약관에 더하고 미리 알립니다.","크레딧은 이 플랫폼의 유료 기능(장표 변환 등)을 쓰는 이용권입니다. 다른 회원에게 넘기거나 팔 수 없고 현금으로 돌려받을 수 없습니다. 결제한 크레딧의 환불은 요금제 공개 때 정하는 환불 조건을 따릅니다.","포인트는 회원 활동(가입·출석·공유 등)에 따라 무상으로 쌓이는 혜택입니다. 이 플랫폼 안에서 정한 곳에만 쓸 수 있고, 넘기거나 팔 수 없으며 현금으로 돌려받을 수 없습니다. 유효 기간이 지나거나 부정하게 쌓은 포인트는 회수할 수 있습니다."]},{"id":"prohibited","title":"제9조 금지 행위","items":["자동화 도구로 서비스를 과도하게 부르거나 호출 한도를 우회하는 행위","다른 회원의 계정·API 키를 쓰거나 나눠 주는 행위","에셋·결과물을 대량으로 내려받아 다시 팔거나 배포하는 행위","서비스 운영을 방해하거나 보안을 위협하는 행위"]},{"id":"removal","title":"제10조 삭제요청","paras":["권리를 침해하거나 개인정보가 드러난 콘텐츠는 삭제요청 페이지로 알려 주세요. 접수 후 48시간 안에 처리합니다."]},{"id":"liability","title":"제11조 책임의 제한","paras":["천재지변·통신 장애처럼 회사가 통제할 수 없는 사유로 생긴 손해는 책임지지 않습니다."]},{"id":"change","title":"제12조 약관 변경","paras":["약관을 바꾸면 시행 7일 전부터 공지사항에 알립니다. 회원에게 불리하면 30일 전부터 알립니다."]},{"id":"law","title":"제13조 준거법·관할","paras":["이 약관은 대한민국 법을 따릅니다. 분쟁은 민사소송법상 관할 법원에서 해결합니다."]}]}', 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM core_policy_versions WHERE doc = 'terms' AND version = '1.1' AND deleted_at IS NULL);
INSERT INTO core_policy_versions (public_id, doc, version, effective_on, summary, spec, published)
SELECT 'pol11privc0034aa', 'privacy', '1.1', '2026-10-17', '국외 이전 표에 이전 시점·방법과 보유 기간 추가', '{"title":"개인정보처리방침","lead":"powerPlus 는 서비스에 꼭 필요한 개인정보만 모으고, 목적이 끝나면 바로 지웁니다.","draft":"이 문서는 법무 검토 전 초안입니다. 정식 공개 전에 내용이 바뀔 수 있습니다.","blocks":[{"id":"collect","title":"1. 수집하는 개인정보","table":{"head":["구분","항목","수집 방법"],"rows":[["회원 가입","이메일, 이름, 프로필 사진, 소셜 계정 식별자","이메일 인증·소셜 로그인"],["선택 입력","생일, 마케팅 수신 동의","마이페이지"],["서비스 이용","접속 기록, IP 주소(끝자리 지움), API 호출 기록","자동 생성"],["업로드","회원이 올린 파일과 그 안의 정보","회원이 직접"],["문의·삭제요청","이름, 소속, 이메일, 연락처","회원이 직접"]]}},{"id":"purpose","title":"2. 이용 목적","items":["회원 식별과 로그인, 임직원 계정 분류","장표 변환·목업 제작 같은 요청 처리","API 키 호출 한도 관리와 부정 이용 방지","문의·삭제요청 처리 결과 안내","동의한 회원에게 새 기능 안내"]},{"id":"retention","title":"3. 보유 기간","paras":["회원 정보는 탈퇴하면 바로 지웁니다.","업로드 파일은 작업이 끝나고 7일 뒤 지웁니다.","접속 기록은 3개월, 관리자 처리 기록은 2년 보관합니다."]},{"id":"entrust","title":"4. 처리 위탁과 국외 이전","paras":["AI 처리를 위해 아래 한 곳에 요청 내용을 보냅니다. 가입할 때 따로 동의를 받습니다."],"table":{"head":["받는 곳","국가","보내는 항목","목적","이전 시점과 방법","보유 기간"],"rows":[["OpenRouter, Inc.","미국","요청 글과 업로드 파일 내용","AI 처리","서비스 이용 중 AI 처리를 요청할 때마다 암호화 통신(HTTPS)으로 전송","처리가 끝나면 지체 없이 파기(받는 곳의 보관 정책에 따름)"]]}},{"id":"rights","title":"5. 이용자의 권리","paras":["마이페이지에서 정보를 고치거나 탈퇴할 수 있습니다.","그 밖의 열람·정정·삭제·처리정지 요청은 문의 양식으로 보내 주세요. 10일 안에 처리합니다."]},{"id":"minor","title":"6. 만 14세 미만","paras":["만 14세 미만의 개인정보는 받지 않습니다. 알게 되면 바로 지웁니다."]},{"id":"cookie","title":"7. 쿠키","paras":["로그인 유지에 세션 쿠키만 씁니다. 광고·추적 쿠키는 쓰지 않습니다."]},{"id":"marketing","title":"8. 마케팅 메일","paras":["새 기능 안내 메일은 동의한 회원에게만 보냅니다. 마이페이지에서 언제든 끌 수 있습니다."]},{"id":"officer","title":"9. 개인정보 보호책임자","paras":["㈜솔리데오 개인정보 보호책임자에게 문의 양식으로 연락해 주세요.","대표전화 02-761-9281"]}]}', 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM core_policy_versions WHERE doc = 'privacy' AND version = '1.1' AND deleted_at IS NULL);
